/**
 * Jinx Fearmonger + Vizier: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Fearmonger
 * Wiki: https://wiki.bloodontheclocktower.com/Vizier
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L115). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import type { ReminderLabel } from '#lib/core/data/index.ts';
import { warned } from '#lib/core/model/fixtures.test-support.ts';
import { executionOutcomes } from '#lib/core/rules/day/execution-outcome.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes/jinx-pairs.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './vizier.test-support.ts';

describe('Fearmonger + Vizier jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'fearmonger', 'vizier');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('fearmonger')?.name).toBe('Fearmonger');
		expect(data.byId.get('vizier')?.name).toBe('Vizier');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['fearmonger', 'vizier'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['fearmonger'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['vizier'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Vizier wakes at the Fearmonger's step, and their execute
	// now doesn't reach the player marked Fear.
	describe("the Vizier wakes with the Fearmonger and can't execute their choice at once", () => {
		const ids = ['vizier', 'fearmonger', 'chef', 'empath', 'poisoner'];
		const base = scenario(ids, { script: scriptOf(ids) });
		const feared = base.reminder('chef', 'fearmonger', 'Fear' as ReminderLabel);

		it("is data in the Vizier's rules", () => {
			expect(jinxRulesBetween('vizier', 'fearmonger', committedCharacters())).toEqual({
				learns: { what: 'partner-choice' },
				noExecuteNow: { player: 'marked', token: 'Fear' }
			});
		});

		it("wakes the Vizier at the Fearmonger's step", () => {
			// Wiki: "The Vizier wakes with the Fearmonger, learns who they choose and cannot choose to
			// immediately execute that player."
			const alerts = nightStepAlerts(base.game, 'fearmonger', base.characters);
			expect(alerts.filter((a) => a.kind === 'wakes-with')).toMatchObject([
				{ seatId: base.seat('vizier'), source: { characterId: 'vizier' }, works: true }
			]);
			const dead = base.dies('vizier');
			expect(
				nightStepAlerts(dead.game, 'fearmonger', dead.characters).some(
					(a) => a.kind === 'wakes-with'
				)
			).toBe(false);
		});

		it('warns on executing the Fear player at once, and not another player', () => {
			// Wiki: "The Vizier wakes with the Fearmonger, learns who they choose and cannot choose to
			// immediately execute that player."
			const s = feared.nominate('empath', 'chef').nominate('poisoner', 'empath');
			const problem = (on: 'chef' | 'empath') =>
				executionOutcomes(s.game, s.seat(on), s.characters).find((o) => o.kind === 'execute-now')
					?.problem;
			expect(problem('chef')).toBe('jinxed');
			expect(problem('empath')).toBeUndefined();
			const outcome = { kind: 'forced', characterId: 'vizier' } as const;
			expect(
				warned(s.session, s.ctx, { type: 'Execute', seatId: s.seat('chef'), outcome })
			).toEqual(['outcome-may-not-apply']);
			// Warn, never lock: the Storyteller may still record it.
			const done = s.do({ type: 'Execute', seatId: s.seat('chef'), outcome });
			expect(done.game.seats[s.seat('chef')].dead).toBe(true);
		});

		it('does not apply with no Fearmonger on the script', () => {
			const plain = ['vizier', 'chef', 'empath', 'poisoner', 'imp'];
			const s = scenario(plain, { script: scriptOf(plain) })
				.reminder('chef', 'fearmonger', 'Fear' as ReminderLabel)
				.nominate('empath', 'chef');
			expect(executionOutcomes(s.game, s.seat('chef'), s.characters)[0]?.problem).toBeUndefined();
		});
	});
});
